import csvimport reimport timefrom pathlib import Pathimport requestsMATCHED_CSV = "matched_targets.csv"BASE_URL = "http://atlas.obs-hp.fr/sophie/sophie.cgi"OUTDIR = Path("data/sophie")OUTDIR.mkdir(parents=True, exist_ok=True)WANTED_FIBERS = {"sky", "wave"}  # lowercasedef read_targets(csv_path: str):    targets = []    with open(csv_path, "r", encoding="utf-8", newline="") as f:        for row in csv.DictReader(f):            name = (row.get("archive_name") or "").strip()            if name:                targets.append(name)    return targetsdef extract_seq_fiber_from_htab(html_text: str):       # Grab each table row    row_blocks = re.findall(r"<tr[^>]*>.*?</tr>", html_text, flags=re.DOTALL | re.IGNORECASE)    out = []    for row in row_blocks:        # seq is a number in the 'seq' column        m_seq = re.search(r"<td[^>]*>\s*(\d{3,})\s*</td>", row, flags=re.IGNORECASE)        # fiber_b is SKY/WAVE/FP etc        m_fib = re.search(r"<td[^>]*>\s*(SKY|WAVE)\s*</td>", row, flags=re.IGNORECASE)        if not (m_seq and m_fib):            continue        seq = m_seq.group(1)        fiber = m_fib.group(1).lower()        if fiber in WANTED_FIBERS:            out.append((seq, fiber))    # de-dupe while preserving order    seen = set()    dedup = []    for item in out:        if item not in seen:            seen.add(item)            dedup.append(item)    return dedupdef download_spectrum(session: requests.Session, seq: str, fiber: str, target_dir: Path):    """    Equivalent of clicking get_spec:      a=mime:application/fits      o=sophie:[sky,SEQ] or o=sophie:[wave,SEQ]    """    params = {        "n": "sophie",        "a": "mime:application/fits",        "o": f"sophie:[{fiber},{seq}]",    }    fname = f"{seq}_{fiber}.fits"    outpath = target_dir / fname    if outpath.exists():        print(f"  Skipping {fname}")        return    print(f"  Downloading {fname}")    with session.get(BASE_URL, params=params, stream=True, timeout=180) as r:        r.raise_for_status()        with outpath.open("wb") as f:            for chunk in r.iter_content(1024 * 1024):                if chunk:                    f.write(chunk)def main():    targets = read_targets(MATCHED_CSV)    print(f"Targets to query: {len(targets)}")    session = requests.Session()    session.headers.update(        {            "User-Agent": "Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7) Safari/605.1.15",            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",        }    )    for t in targets:        print(f"\n=== {t} ===")        safe_name = re.sub(r"[^\w\-\+\.]", "_", t)        tdir = OUTDIR / safe_name        tdir.mkdir(parents=True, exist_ok=True)        # Query by object name, but use HTAB because it contains seq + fiber columns.        params = {            "n": "sophie",            "c": "o",            "a": "htab",            "o": t,        }        try:            print("  Querying archive...")            r = session.get(BASE_URL, params=params, timeout=90)            r.raise_for_status()            observations = extract_seq_fiber_from_htab(r.text)            print(f"  Found {len(observations)} SKY/WAVE rows")            if not observations:                continue            for seq, fiber in observations:                try:                    download_spectrum(session, seq, fiber, tdir)                except Exception as e:                    print(f"    FAILED {seq}_{fiber}: {e}")                time.sleep(0.5)        except Exception as e:            print(f"  FAILED to process {t}: {e}")        time.sleep(2)if __name__ == "__main__":    main()